static int set_error(char *error, size_t capacity, const char *format, ...)
{
    if (error != NULL && capacity != 0U) {
        va_list arguments;
        va_start(arguments, format);
        (void)vsnprintf(error, capacity, format, arguments);
        va_end(arguments);
    }
    return -1;
}

static bool token_is_category(hstex_token token, enum hstex_catcode category)
{
    return hstex_token_is_character(token) &&
           hstex_token_category(token) == (uint8_t)category;
}

static bool token_is_space(hstex_token token)
{
    return token_is_category(token, HSTEX_CAT_SPACE);
}

static bool token_is_other_character(hstex_token token, uint8_t character)
{
    return hstex_token_is_character(token) &&
           hstex_token_category(token) == (uint8_t)HSTEX_CAT_OTHER &&
           hstex_token_character_code(token) == character;
}

static hstex_token normalize_unexpanded_control_sequence(hstex_token token)
{
    if (hstex_token_is_unexpanded_control_sequence(token)) {
        return hstex_token_control_sequence(
            hstex_token_control_sequence_id(token));
    }
    return token;
}

static hstex_token normalize_one_shot_token(hstex_token token)
{
    token = normalize_unexpanded_control_sequence(token);
    if (hstex_token_is_unexpanded_non_control(token)) {
        token = hstex_token_normalize_unexpanded_non_control(token);
    }
    return token;
}

static hstex_token normalize_frozen_control_sequence(hstex_token token)
{
    if (hstex_token_is_frozen_control_sequence(token)) {
        return hstex_token_control_sequence(
            hstex_token_control_sequence_id(token));
    }
    return token;
}

static bool token_is_effective_space(const struct hstex_engine *engine,
                                     hstex_token token)
{
    if (token_is_space(token)) {
        return true;
    }
    if (engine == NULL || !hstex_token_is_control_sequence(token)) {
        return false;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
           token_is_space(meaning->value.token);
}

/* An implicit begin-group character - a control sequence \let to a catcode-1
   token - opens a box just as an explicit brace does, because TeX inspects the
   meaning rather than the token. Balanced-text scanning is deliberately not
   changed: pdfTeX runs off the end of the file on \toks0=\bgroup abc\egroup,
   so there only explicit braces count. See docs/DECISIONS.md, implicit-braces. */
static bool token_is_effective_begin_group(struct hstex_engine *engine,
                                           hstex_token token)
{
    if (token_is_category(token, HSTEX_CAT_BEGIN_GROUP)) {
        return true;
    }
    if (engine == NULL || !hstex_token_is_control_sequence(token)) {
        return false;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
           token_is_category(meaning->value.token, HSTEX_CAT_BEGIN_GROUP);
}

/* The preamble is read without expansion, so a control sequence \let to a
   parameter or tab character has to be recognised by its meaning -- which is
   how LaTeX's \@sharp reaches \halign. */
static bool token_is_effective_category(struct hstex_engine *engine,
                                        hstex_token token, uint8_t category)
{
    if (token_is_category(token, category)) {
        return true;
    }
    if (engine == NULL || !hstex_token_is_control_sequence(token)) {
        return false;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
           token_is_category(meaning->value.token, category);
}

static bool token_is_effective_end_group(struct hstex_engine *engine,
                                         hstex_token token)
{
    if (token_is_category(token, HSTEX_CAT_END_GROUP)) {
        return true;
    }
    if (engine == NULL || !hstex_token_is_control_sequence(token)) {
        return false;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
           token_is_category(meaning->value.token, HSTEX_CAT_END_GROUP);
}


static int code_table_index(enum hstex_command command)
{
    switch (command) {
    case HSTEX_COMMAND_SF_CODE:
        return 0;
    case HSTEX_COMMAND_LC_CODE:
        return 1;
    case HSTEX_COMMAND_UC_CODE:
        return 2;
    case HSTEX_COMMAND_MATH_CODE:
        return 3;
    case HSTEX_COMMAND_DEL_CODE:
        return 4;
    default:
        return -1;
    }
}

/* Token arrays are taken and given back about eight million times over the
   corpus -- one for the body of nearly every definition it makes -- in sizes
   that are nearly all a few tokens. They come from free lists of their own,
   one for each power of two, so that making a definition costs a pointer
   read rather than a walk into the allocator and back.

   A block is an ordinary allocation, and the list is threaded through the
   first eight bytes of a free one, so anything that leaves the pool for good
   can still be given back to the library in the usual way. The lists belong
   to the process rather than to any one engine, which is what lets a body
   given back where the engine is known be taken again where it is not. */
#define HSTEX_TOKEN_POOL_LEAST 8U
#define HSTEX_TOKEN_POOL_CLASSES 12U
#define HSTEX_TOKEN_POOL_MOST \
    (HSTEX_TOKEN_POOL_LEAST << (HSTEX_TOKEN_POOL_CLASSES - 1U))

static hstex_token *token_pool[HSTEX_TOKEN_POOL_CLASSES];

/* The block a run of `count` tokens is kept in: the least power of two that
   holds it, and never fewer than eight. A vector's own capacity is arrived
   at the same way, so a body may be given back knowing only how long it is. */
static size_t token_pool_capacity(size_t count)
{
    size_t capacity = HSTEX_TOKEN_POOL_LEAST;
    while (capacity < count) {
        capacity *= 2U;
    }
    return capacity;
}

static unsigned token_pool_class(size_t capacity)
{
    unsigned found = 0U;
    size_t size = HSTEX_TOKEN_POOL_LEAST;
    while (size < capacity) {
        size *= 2U;
        ++found;
    }
    return found;
}

static hstex_token *token_pool_take(size_t capacity)
{
    if (capacity > (size_t)HSTEX_TOKEN_POOL_MOST) {
        return NULL;
    }
    unsigned found = token_pool_class(capacity);
    hstex_token *block = token_pool[found];
    if (block == NULL) {
        return NULL;
    }
    hstex_token *next = NULL;
    memcpy(&next, block, sizeof(next));
    token_pool[found] = next;
    return block;
}

/* True where the pool has taken the block; false where it is too big for any
   of the lists and belongs to the library instead. */
static bool token_pool_give(hstex_token *block, size_t capacity)
{
    if (block == NULL) {
        return true;
    }
    if (capacity > (size_t)HSTEX_TOKEN_POOL_MOST) {
        return false;
    }
    unsigned found = token_pool_class(capacity);
    hstex_token *next = token_pool[found];
    memcpy(block, &next, sizeof(next));
    token_pool[found] = block;
    return true;
}

/* Room for a run of tokens, from the pool where it has any. Everything that
   may later be given back by length alone -- a definition's body, the tokens
   a frame owns -- must be asked for here, so that what is given back is
   always at least as big as the list it goes on. */
static hstex_token *token_block_alloc(size_t count)
{
    size_t capacity = token_pool_capacity(count);
    hstex_token *block = token_pool_take(capacity);
    if (block != NULL) {
        return block;
    }
    if (capacity > SIZE_MAX / sizeof(*block)) {
        return NULL;
    }
    return malloc(capacity * sizeof(*block));
}

/* What a definition's body is given back to when nothing holds it any more.
   How long it is says which list it belongs on, because that is how the
   room for it was arrived at. */
static void token_block_free(hstex_token *block, size_t count)
{
    if (block == NULL) {
        return;
    }
    if (!token_pool_give(block, token_pool_capacity(count))) {
        free(block);
    }
}

static void vector_destroy(struct hstex_token_vector *vector)
{
    if (vector->data != NULL && !token_pool_give(vector->data,
                                                 vector->capacity)) {
        free(vector->data);
    }
    memset(vector, 0, sizeof(*vector));
}

static int vector_reserve(struct hstex_token_vector *vector, size_t required,
                          char *error, size_t error_capacity)
{
    if (required <= vector->capacity) {
        return 0;
    }
    /* A vector starts at eight tokens rather than thirty-two and doubles
       from there. Three definitions in four have a body of seven tokens or
       fewer, and starting every one of the corpus's seven million of them
       at thirty-two asked for four times the tokens they hold. Doubling is
       kept, so a vector filled a token at a time still grows in as few
       steps as it did. */
    size_t capacity = vector->capacity == 0U ? 8U : vector->capacity;
    while (capacity < required) {
        if (capacity > SIZE_MAX / 2U) {
            return set_error(error, error_capacity,
                             "token-vector capacity overflow");
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*vector->data)) {
        return set_error(error, error_capacity,
                         "token-vector allocation overflow");
    }
    hstex_token *taken = token_pool_take(capacity);
    if (taken != NULL) {
        if (vector->count != 0U) {
            memcpy(taken, vector->data, vector->count * sizeof(*taken));
        }
        if (vector->data != NULL &&
            !token_pool_give(vector->data, vector->capacity)) {
            free(vector->data);
        }
        vector->data = taken;
        vector->capacity = capacity;
        return 0;
    }
    void *allocation = realloc(vector->data, capacity * sizeof(*vector->data));
    if (allocation == NULL) {
        return set_error(error, error_capacity,
                         "token-vector allocation failed");
    }
    vector->data = allocation;
    vector->capacity = capacity;
    return 0;
}

/* Tokens moved from one place to another. A run of them is usually a few
   words long -- an argument, a body, the tail of a group -- and going out to
   the library to move sixteen bytes costs more than moving them here. */
static inline void copy_tokens(hstex_token *to, const hstex_token *from,
                               size_t count)
{
    if (count > 16U) {
        memcpy(to, from, count * sizeof(*to));
        return;
    }
    for (size_t index = 0U; index < count; ++index) {
        to[index] = from[index];
    }
}

static int vector_push(struct hstex_token_vector *vector, hstex_token token,
                       char *error, size_t error_capacity)
{
    if (vector_reserve(vector, vector->count + 1U, error, error_capacity) != 0) {
        return -1;
    }
    vector->data[vector->count++] = token;
    return 0;
}

static int reserve_meanings(struct hstex_engine *engine, size_t required,
                            char *error, size_t error_capacity)
{
    if (required <= engine->meaning_capacity) {
        return 0;
    }
    size_t capacity = engine->meaning_capacity == 0U
                          ? (size_t)HSTEX_INITIAL_MEANING_CAPACITY
                          : engine->meaning_capacity;
    while (capacity < required) {
        if (capacity > SIZE_MAX / 2U) {
            return set_error(error, error_capacity,
                             "meaning-table capacity overflow");
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*engine->meanings)) {
        return set_error(error, error_capacity,
                         "meaning-table allocation overflow");
    }
    size_t old_capacity = engine->meaning_capacity;
    void *allocation = realloc(engine->meanings,
                               capacity * sizeof(*engine->meanings));
    if (allocation == NULL) {
        return set_error(error, error_capacity,
                         "meaning-table allocation failed");
    }
    engine->meanings = allocation;
    memset(engine->meanings + old_capacity, 0,
           (capacity - old_capacity) * sizeof(*engine->meanings));
    engine->meaning_capacity = capacity;
    return 0;
}

